import numpy as np
from scipy import stats
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong univariate predictors (p < 0.05)
    strong_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue  # Skip derived features
        t_stat = stats.ttest_ind(feats.x[:,i][feats.y==1], feats.x[:,i][feats.y==0]).statistic
        p_val = stats.ttest_ind(feats.x[:,i][feats.y==1], feats.x[:,i][feats.y==0]).pvalue
        if p_val < 0.05:
            strong_features.append((fid, abs(t_stat)))

    # Sort by effect size
    strong_features.sort(key=lambda x: x[1], reverse=True)

    # Remove near-duplicates (correlated with |r| > 0.6)
    correlated_pairs = set()
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            r = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
            if abs(r) >= 0.6:
                fid1, fid2 = feats.ids[i], feats.ids[j]
                correlated_pairs.add((min(fid1,fid2), max(fid1,fid2)))

    # Group correlated features into clusters
    clusters = defaultdict(set)
    for fid1, fid2 in correlated_pairs:
        clusters[fid1].add(fid2)
        clusters[fid2].add(fid1)

    # Select representative from each cluster
    selected_features = set()
    for fid, _ in strong_features:
        if any(fid in clusters[fid2] for fid2 in selected_features):
            continue  # Skip if already in cluster
        selected_features.add(fid)

    # If no strong features, return empty design
    if not selected_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top 4 features as drivers (to keep model small)
    drivers = tuple(list(selected_features)[:4])

    # Include all selected features in the regression
    columns = tuple(selected_features)

    # Look for product terms between top features (limit to 3 pairs max)
    products = []
    count = 0
    for i, fid1 in enumerate(drivers):
        for j, fid2 in enumerate(drivers[i+1:], i+1):
            if count >= 3:
                break
            products.append((fid1, fid2))
            count += 1

    # Weighted score: sum of top features with weights based on effect sizes
    loadings = {}
    for fid, _ in strong_features[:len(drivers)]:
        # Use t-statistic as weight
        idx = feats.column(fid)
        t_stat = stats.ttest_ind(feats.x[:,idx][feats.y==1], feats.x[:,idx][feats.y==0]).statistic
        loadings[fid] = abs(t_stat)

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)
